def get_concept(session: Session, concept_code: str) -> Optional[MetricConcept]:
    return session.get(MetricConcept, concept_code)


def list_labels_for_concept(session: Session, concept_code: str) -> list[MetricLabel]:
    stmt = (
        select(MetricLabel)
        .where(MetricLabel.concept_code == concept_code)
        .order_by(MetricLabel.is_primary.desc(), MetricLabel.label_kind, MetricLabel.id)  # type: ignore[attr-defined]
    )
    return list(session.exec(stmt).all())


def list_implementations_for_concept(
    session: Session, concept_code: str
) -> list[MetricImplementation]:
    stmt = (
        select(MetricImplementation)
        .where(MetricImplementation.concept_code == concept_code)
        .order_by(
            MetricImplementation.is_primary.desc(),  # type: ignore[attr-defined]
            MetricImplementation.impl_status,
            MetricImplementation.table_fqn,
            MetricImplementation.id,
        )
    )
    return list(session.exec(stmt).all())


def collect_dim_names_from_impls(impls: list[MetricImplementation]) -> list[str]:
    """从 impl.dim_uses JSON 抽出维度名（兼容 str / {dim|name|dimension}）。"""
    seen: list[str] = []
    for impl in impls:
        raw: Any = impl.dim_uses
        if not raw:
            continue
        items = raw if isinstance(raw, list) else [raw]
        for item in items:
            name = None
            if isinstance(item, str):
                name = item.strip()
            elif isinstance(item, dict):
                name = (
                    item.get("dim")
                    or item.get("name")
                    or item.get("dimension")
                    or item.get("dimension_name")
                )
                if name:
                    name = str(name).strip()
            if name and name not in seen:
                seen.append(name)
    return seen


def list_dimensions_for_entity(
    session: Session, entity_code: Optional[str], limit: int = 40
) -> list[DimensionStandard]:
    if not entity_code:
        return []
    stmt = (
        select(DimensionStandard)
        .where(DimensionStandard.entity_code == entity_code)
        .order_by(DimensionStandard.name)
        .limit(limit)
    )
    return list(session.exec(stmt).all())

