"""指标库概念层 web UI（v0.3 · Phase0/1 只读）。

挂在 /metrics/concept/*，避开 /metrics/{name} 与标准指标名冲突。
"""
from __future__ import annotations

from typing import Optional

from fastapi import APIRouter, Depends, HTTPException, Request
from fastapi.responses import RedirectResponse
from sqlmodel import Session

from app.dependencies import get_session, require_auth
from app.services import metric_concept_layer_service
from app.templating import templates

router = APIRouter(
    prefix="/metrics/concept",
    tags=["metric-concept-ui"],
    dependencies=[Depends(require_auth)],
)

# 零件字典 tabs（概念指标 / 标准指标 / 审核在 _subnav 里单独排）
_DICT_TABS = [
    ("entities", "实体", "/metrics/concept/entities"),
    ("roles", "角色", "/metrics/concept/roles"),
    ("event_ext", "事件归属", "/metrics/concept/event-ext"),
]


def _concept_ctx(**extra):
    return {
        "concept_tabs": list(_DICT_TABS),
        **extra,
    }


@router.get("")
def concept_home():
    # 知秋：概念指标作默认入口（不再落到 entities）
    return RedirectResponse("/metrics/concept/concepts", status_code=303)


@router.get("/entities")
def entities_list(
    request: Request,
    status: Optional[str] = None,
    session: Session = Depends(get_session),
):
    rows = metric_concept_layer_service.list_entities(
        session, status=status or None, limit=200
    )
    return templates.TemplateResponse(
        request,
        "metrics/concept/entities.html",
        _concept_ctx(
            active_tab="entities",
            items=rows,
            total=len(rows),
            status=status or "",
            status_options=["", "draft", "published", "deprecated"],
        ),
    )


@router.get("/entities/{entity_code}")
def entity_detail(
    request: Request,
    entity_code: str,
    session: Session = Depends(get_session),
):
    row = metric_concept_layer_service.get_entity(session, entity_code)
    if not row:
        raise HTTPException(404, f"实体 `{entity_code}` 不存在")
    events = metric_concept_layer_service.list_event_ext(
        session, entity_code=entity_code, limit=200
    )
    return templates.TemplateResponse(
        request,
        "metrics/concept/entity_detail.html",
        _concept_ctx(active_tab="entities", entity=row, events=events),
    )


@router.get("/roles")
def roles_list(
    request: Request,
    status: Optional[str] = None,
    session: Session = Depends(get_session),
):
    rows = metric_concept_layer_service.list_roles(
        session, status=status or None, limit=200
    )
    return templates.TemplateResponse(
        request,
        "metrics/concept/roles.html",
        _concept_ctx(
            active_tab="roles",
            items=rows,
            total=len(rows),
            status=status or "",
            status_options=["", "draft", "published", "deprecated"],
        ),
    )


@router.get("/roles/{role_code}")
def role_detail(
    request: Request,
    role_code: str,
    session: Session = Depends(get_session),
):
    row = metric_concept_layer_service.get_role(session, role_code)
    if not row:
        raise HTTPException(404, f"角色 `{role_code}` 不存在")
    return templates.TemplateResponse(
        request,
        "metrics/concept/role_detail.html",
        _concept_ctx(active_tab="roles", role=row),
    )


@router.get("/event-ext")
def event_ext_list(
    request: Request,
    entity_code: Optional[str] = None,
    session: Session = Depends(get_session),
):
    rows = metric_concept_layer_service.list_event_ext(
        session, entity_code=entity_code or None, limit=500
    )
    entities = metric_concept_layer_service.list_entities(session, limit=100)
    empty_raw = sum(1 for r in rows if not (r.raw_table_fqn or "").strip())
    return templates.TemplateResponse(
        request,
        "metrics/concept/event_ext.html",
        _concept_ctx(
            active_tab="event_ext",
            items=rows,
            total=len(rows),
            empty_raw=empty_raw,
            entity_code=entity_code or "",
            entity_options=entities,
        ),
    )


@router.get("/event-ext/{event_code}")
def event_ext_detail(
    request: Request,
    event_code: str,
    session: Session = Depends(get_session),
):
    row = metric_concept_layer_service.get_event_ext(session, event_code)
    if not row:
        raise HTTPException(404, f"事件归属 `{event_code}` 不存在")
    return templates.TemplateResponse(
        request,
        "metrics/concept/event_ext_detail.html",
        _concept_ctx(active_tab="event_ext", event=row),
    )


@router.get("/concepts")
def concepts_list(
    request: Request,
    q: Optional[str] = None,
    lifecycle_status: Optional[str] = None,
    entity_code: Optional[str] = None,
    session: Session = Depends(get_session),
):
    rows = metric_concept_layer_service.list_concepts(
        session,
        q=q or None,
        lifecycle_status=lifecycle_status or None,
        entity_code=entity_code or None,
        limit=500,
    )
    entities = metric_concept_layer_service.list_entities(session, limit=100)
    return templates.TemplateResponse(
        request,
        "metrics/concept/concepts.html",
        _concept_ctx(
            active_tab="concepts",
            items=rows,
            total=len(rows),
            q=q or "",
            lifecycle_status=lifecycle_status or "",
            entity_code=entity_code or "",
            status_options=["", "draft", "published", "deprecated", "orphaned"],
            entity_options=entities,
        ),
    )


@router.get("/concepts/{concept_code}")
def concept_detail(
    request: Request,
    concept_code: str,
    session: Session = Depends(get_session),
):
    row = metric_concept_layer_service.get_concept(session, concept_code)
    if not row:
        raise HTTPException(404, f"概念指标 `{concept_code}` 不存在")
    labels = metric_concept_layer_service.list_labels_for_concept(session, concept_code)
    impls = metric_concept_layer_service.list_implementations_for_concept(
        session, concept_code
    )
    dim_from_impl = metric_concept_layer_service.collect_dim_names_from_impls(impls)
    entity_dims = metric_concept_layer_service.list_dimensions_for_entity(
        session, row.entity_code, limit=24
    )
    # 关系图维度：优先 impl.dim_uses；否则用实体下 dimension_standard
    graph_dims: list[str] = list(dim_from_impl)
    if not graph_dims:
        graph_dims = [d.name for d in entity_dims]
    return templates.TemplateResponse(
        request,
        "metrics/concept/concept_detail.html",
        _concept_ctx(
            active_tab="concepts",
            concept=row,
            labels=labels,
            implementations=impls,
            graph_dims=graph_dims,
            dim_source="impl" if dim_from_impl else ("entity" if entity_dims else "none"),
        ),
    )

