{% extends "base.html" %}

{% block content %}
{% include "metrics/concept/_subnav.html" %}

<p><a href="/metrics/concept/concepts">← 返回概念列表</a></p>
<h1>概念指标 · <code>{{ concept.concept_code }}</code></h1>
<p class="muted">
  {{ concept.metric_kind }} ·
  <span class="badge badge-{{ concept.lifecycle_status }}">{{ concept.lifecycle_status }}</span>
</p>

{# —— ① 是什么 —— #}
<section class="section-block">
  <h2>① 是什么</h2>
  <table class="kv-table">
    <tr><th>定义</th><td>{{ concept.definition or '-' }}</td></tr>
    <tr>
      <th>实体</th>
      <td>
        {% if concept.entity_code %}
          <a href="/metrics/concept/entities/{{ concept.entity_code }}"><code>{{ concept.entity_code }}</code></a>
        {% else %}-{% endif %}
      </td>
    </tr>
    <tr>
      <th>主事件</th>
      <td>
        {% if concept.main_event_code %}
          <a href="/metrics/concept/event-ext/{{ concept.main_event_code }}"><code>{{ concept.main_event_code }}</code></a>
        {% else %}-{% endif %}
      </td>
    </tr>
    <tr>
      <th>相关事件</th>
      <td>
        {% if concept.related_event_codes %}
          {% for ev in concept.related_event_codes %}
            <a href="/metrics/concept/event-ext/{{ ev }}"><code>{{ ev }}</code></a>{% if not loop.last %} · {% endif %}
          {% endfor %}
        {% else %}-{% endif %}
      </td>
    </tr>
    <tr><th>时间窗口</th><td>{{ concept.time_window or '-' }}</td></tr>
    <tr><th>默认聚合</th><td>{{ concept.default_aggregation or '-' }}</td></tr>
    <tr><th>layer</th><td>{{ concept.layer or '-' }}</td></tr>
    <tr><th>需求引用</th><td>{{ concept.req_ref or '-' }}</td></tr>
    <tr><th>备注</th><td>{{ concept.note or '-' }}</td></tr>
  </table>
</section>

{# —— 关系图（知秋：SVG / 白底浅色） —— #}
<section class="section-block">
  <h2>关系图 · 实体 / 事件 / 维度</h2>
  <p class="muted" style="margin-top:0;">
    指标属于哪个实体 → 度量哪个主事件 → 可按哪些维度切分
    {% if dim_source == "impl" %}（维度来自实现 dim_uses）
    {% elif dim_source == "entity" %}（实现尚未填 dim_uses，暂用实体下维度字典）
    {% else %}（暂无维度数据）{% endif %}
  </p>
  {% set dims = graph_dims if graph_dims is defined else [] %}
  {% set dim_n = dims|length %}
  {% set svg_h = 220 if dim_n <= 4 else (220 + (dim_n - 4) * 36) %}
  <div class="relation-svg-wrap">
    <svg xmlns="http://www.w3.org/2000/svg" width="760" height="{{ svg_h }}" viewBox="0 0 760 {{ svg_h }}" role="img" aria-label="指标关系图">
      <rect x="0" y="0" width="760" height="{{ svg_h }}" fill="#ffffff"/>
      {# concept #}
      <rect x="20" y="80" width="150" height="56" rx="8" fill="#e3f2fd" stroke="#90caf9" stroke-width="1.5"/>
      <text x="95" y="102" text-anchor="middle" font-size="11" fill="#546e7a">概念指标</text>
      <text x="95" y="120" text-anchor="middle" font-size="12" font-weight="600" fill="#1565c0">{{ concept.concept_code[:18] }}{% if concept.concept_code|length > 18 %}…{% endif %}</text>
      {# entity #}
      <rect x="230" y="20" width="150" height="56" rx="8" fill="#e8f5e9" stroke="#a5d6a7" stroke-width="1.5"/>
      <text x="305" y="42" text-anchor="middle" font-size="11" fill="#546e7a">实体</text>
      <text x="305" y="60" text-anchor="middle" font-size="12" font-weight="600" fill="#2e7d32">{{ concept.entity_code or '（未填）' }}</text>
      {# event #}
      <rect x="230" y="140" width="150" height="56" rx="8" fill="#fff8e1" stroke="#ffe082" stroke-width="1.5"/>
      <text x="305" y="162" text-anchor="middle" font-size="11" fill="#546e7a">主事件</text>
      <text x="305" y="180" text-anchor="middle" font-size="12" font-weight="600" fill="#f57f17">{{ (concept.main_event_code or '（未填）')[:18] }}</text>
      {# arrows concept -> entity / event #}
      <line x1="170" y1="95" x2="230" y2="55" stroke="#90a4ae" stroke-width="1.5" marker-end="url(#arrow)"/>
      <line x1="170" y1="120" x2="230" y2="160" stroke="#90a4ae" stroke-width="1.5" marker-end="url(#arrow)"/>
      <defs>
        <marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto">
          <path d="M0,0 L6,3 L0,6 Z" fill="#90a4ae"/>
        </marker>
      </defs>
      {# dimensions column #}
      <text x="520" y="18" text-anchor="middle" font-size="11" fill="#546e7a">可用维度</text>
      {% if dim_n == 0 %}
        <rect x="450" y="80" width="160" height="48" rx="8" fill="#fafafa" stroke="#e0e0e0" stroke-width="1.5"/>
        <text x="530" y="108" text-anchor="middle" font-size="12" fill="#9e9e9e">暂无</text>
