      {% else %}
        {% for d in dims[:12] %}
          {% set dy = 36 + loop.index0 * 36 %}
          <rect x="450" y="{{ dy }}" width="160" height="30" rx="6" fill="#f3e5f5" stroke="#ce93d8" stroke-width="1.2"/>
          <text x="530" y="{{ dy + 20 }}" text-anchor="middle" font-size="12" fill="#6a1b9a">{{ d[:20] }}{% if d|length > 20 %}…{% endif %}</text>
          <line x1="380" y1="148" x2="450" y2="{{ dy + 15 }}" stroke="#ce93d8" stroke-width="1.2" opacity="0.7"/>
        {% endfor %}
        {% if dim_n > 12 %}
          <text x="530" y="{{ 36 + 12 * 36 }}" text-anchor="middle" font-size="11" fill="#9e9e9e">…另有 {{ dim_n - 12 }} 个</text>
        {% endif %}
      {% endif %}
    </svg>
  </div>
  <p class="muted" style="font-size:0.85em;">
    {% if concept.entity_code %}实体详情：<a href="/metrics/concept/entities/{{ concept.entity_code }}"><code>{{ concept.entity_code }}</code></a>{% endif %}
    {% if concept.main_event_code %} · 事件详情：<a href="/metrics/concept/event-ext/{{ concept.main_event_code }}"><code>{{ concept.main_event_code }}</code></a>{% endif %}
  </p>
</section>

{# —— ② 怎么叫 —— #}
<section class="section-block">
  <h2>② 怎么叫 · 标签（{{ labels|length }}）</h2>
  {% if labels %}
  <table>
    <thead>
      <tr>
        <th>label_kind</th>
        <th>label_text</th>
        <th>主名</th>
      </tr>
    </thead>
    <tbody>
      {% for lb in labels %}
      <tr>
        <td><code>{{ lb.label_kind }}</code></td>
        <td>{{ lb.label_text }}</td>
        <td>{% if lb.is_primary %}<span class="badge badge-primary-impl">主</span>{% else %}-{% endif %}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  {% else %}
  <p class="muted">暂无标签。</p>
  {% endif %}
</section>

{# —— ③ 在哪实现 · 怎么实现 —— #}
<section class="section-block">
  <h2>③ 在哪实现 · 怎么实现（{{ implementations|length }}）</h2>
  {% if implementations %}
  <table>
    <thead>
      <tr>
        <th>落点</th>
        <th>粒度</th>
        <th>聚合</th>
        <th>主从</th>
        <th>状态</th>
        <th>formula</th>
      </tr>
    </thead>
    <tbody>
      {% for impl in implementations %}
      <tr class="{% if impl.is_primary %}impl-primary-row{% endif %}">
        <td>
          {% set parts = impl.table_fqn.split('.') %}
          {% if parts|length == 2 %}
            <a href="/tables/{{ parts[0] }}/{{ parts[1] }}"><code>{{ impl.table_fqn }}</code></a>{% if impl.column_name %}.<code>{{ impl.column_name }}</code>{% endif %}
          {% else %}
            <code>{{ impl.table_fqn }}{% if impl.column_name %}.{{ impl.column_name }}{% endif %}</code>
          {% endif %}
        </td>
        <td>{{ impl.storage_granularity or '-' }}</td>
        <td>{{ impl.aggregation or '-' }}</td>
        <td>
          {% if impl.is_primary %}
            <span class="badge badge-primary-impl">主实现</span>
          {% else %}
            <span class="muted">从</span>
          {% endif %}
        </td>
        <td><span class="badge badge-{{ impl.impl_status }}">{{ impl.impl_status }}</span></td>
        <td><code style="white-space:pre-wrap;font-size:0.85em;">{{ impl.formula or '-' }}</code></td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  {% else %}
  <p class="muted">
    {% if concept.metric_kind == 'constant' %}
      常数 helper（metric_kind=constant），无表级实现属正常。
    {% else %}
      暂无实现行。
    {% endif %}
  </p>
  {% endif %}
</section>

{# —— ④ 怎么构成（仅 derived） —— #}
{% if concept.metric_kind == 'derived' %}
<section class="section-block">
  <h2>④ 怎么构成 · 分子 / 分母</h2>
  <table class="kv-table">
    <tr>
      <th>分子</th>
      <td>
        {% if concept.numerator_concept_code %}
          <a href="/metrics/concept/concepts/{{ concept.numerator_concept_code }}"><code>{{ concept.numerator_concept_code }}</code></a>
        {% else %}-{% endif %}
      </td>
    </tr>
    <tr>
      <th>分母</th>
      <td>
        {% if concept.denominator_concept_code %}
          <a href="/metrics/concept/concepts/{{ concept.denominator_concept_code }}"><code>{{ concept.denominator_concept_code }}</code></a>
        {% else %}-{% endif %}
      </td>
    </tr>
  </table>
</section>
{% endif %}

{% endblock %}

